"""Self-contained portfolio dashboard for the synthetic local demo."""

from __future__ import annotations


DASHBOARD_HTML = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark">
<title>TraceGate Edge</title>
<style>
:root{--bg:#07111f;--panel:#0e1b2e;--panel2:#13233a;--line:#263c59;--text:#edf6ff;--muted:#91a7c1;--cyan:#45d7f5;--green:#43dfa2;--amber:#ffc760;--red:#ff7287;--violet:#aa8cff;--shadow:0 24px 70px #0007}
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 15% -10%,#173e60 0,transparent 40%),radial-gradient(circle at 95% 5%,#33215e 0,transparent 28%),var(--bg);color:var(--text);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}.shell{max-width:1440px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.eyebrow,.label{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);font-weight:800}.brand{font-size:clamp(30px,5vw,52px);line-height:1;font-weight:900;letter-spacing:-2px;margin:7px 0}.brand em{font-style:normal;color:var(--cyan)}.subtitle{color:var(--muted);max-width:660px}.badges{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.badge,.status{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--line);background:#11233a;border-radius:999px;padding:7px 11px;font-size:12px;font-weight:800}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green)}.dot.bad{background:var(--red);box-shadow:0 0 12px var(--red)}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:24px 0}.card{background:linear-gradient(145deg,#12223aee,#0c182aee);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow)}.stat{padding:16px}.stat b{display:block;font:850 27px/1.2 ui-monospace,SFMono-Regular,monospace;margin-top:4px}.grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(340px,.8fr);gap:16px}.section{padding:19px}.section h2{font-size:18px;margin:4px 0 15px}.unitbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap}select,input,textarea{background:#071322;border:1px solid #355071;color:var(--text);border-radius:10px;padding:11px 12px;outline:none;font:inherit}select:focus,input:focus,textarea:focus{border-color:var(--cyan);box-shadow:0 0 0 3px #45d7f522}button{border:0;border-radius:10px;padding:11px 14px;background:var(--cyan);color:#06121d;font-weight:850;cursor:pointer}button:hover{filter:brightness(1.08)}button:disabled{opacity:.4;cursor:not-allowed}button.alt{background:#213652;color:var(--text);border:1px solid #385373}button.warn{background:var(--amber)}button.danger{background:var(--red)}.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0}.fact{padding:12px;background:#091626;border:1px solid #1f3652;border-radius:12px}.fact strong{display:block;margin-top:4px;font-size:14px;overflow-wrap:anywhere}.route{display:grid;grid-template-columns:repeat(7,1fr);gap:7px;margin:14px 0 20px}.step{min-width:0;padding:10px 7px;text-align:center;background:#091626;border:1px solid #263d5c;border-radius:11px;color:var(--muted);font-size:11px}.step b{display:block;color:inherit;font-size:12px}.step.done{color:var(--green);border-color:#2a765d}.step.current{color:#05131e;background:var(--cyan);border-color:var(--cyan);box-shadow:0 0 24px #45d7f544}.actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.action{padding:14px;background:#0a1728;border:1px solid #243a57;border-radius:14px}.action h3{font-size:14px;margin:0 0 9px}.action .row{display:flex;gap:7px;flex-wrap:wrap}.action input,.action select{min-width:0;flex:1}.full{grid-column:1/-1}.requirements,.interfaces{display:flex;gap:7px;flex-wrap:wrap}.chip{padding:6px 9px;border-radius:999px;background:#172943;border:1px solid #2a4263;font-size:12px}.chip.ok{color:var(--green);border-color:#2a765d}.chip.bad{color:var(--red);border-color:#7d3345}.console{min-height:94px;margin-top:12px;padding:12px;border-radius:12px;background:#06101d;border:1px solid #1e344f;font:12px/1.55 ui-monospace,SFMono-Regular,monospace;white-space:pre-wrap;overflow-wrap:anywhere;color:#bfd0e5}.console.ok{border-color:#277055}.console.bad{border-color:#7d3345}.timeline{display:grid;gap:8px;max-height:370px;overflow:auto}.event{padding:11px 12px;border-left:3px solid var(--cyan);background:#091626;border-radius:5px 11px 11px 5px}.event small{color:var(--muted)}.empty{color:var(--muted);padding:18px 0}.table{width:100%;border-collapse:collapse;font-size:12px}.table td,.table th{text-align:left;border-bottom:1px solid #223752;padding:8px 5px}.table th{color:var(--muted)}.PENDING,.RETRY{color:var(--amber)}.DELIVERED{color:var(--green)}.DEAD_LETTER{color:var(--red)}.explain{border:1px solid #58467b;background:#17142a;padding:13px;border-radius:12px;color:#d8cdf4}.fine{font-size:12px;color:var(--muted);margin-top:16px}.footer{text-align:center;color:var(--muted);padding:24px 0 5px;font-size:12px}
@media(max-width:1000px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.shell{padding:16px}.top{flex-direction:column}.badges{justify-content:flex-start}.stats{grid-template-columns:repeat(2,1fr)}.facts{grid-template-columns:repeat(2,1fr)}.route{grid-template-columns:repeat(4,1fr)}.actions{grid-template-columns:1fr}.full{grid-column:auto}}
</style>
</head>
<body><main class="shell">
  <header class="top">
    <div><div class="eyebrow">Synthetic manufacturing systems lab</div><div class="brand">TraceGate <em>Edge</em></div><div class="subtitle">Deterministic station control, product genealogy, repair/retest and an offline-first transactional outbox—built for explainable evidence, not magic PASS buttons.</div></div>
    <div class="badges"><span class="badge"><span id="healthDot" class="dot"></span><span id="healthText">Checking edge</span></span><span class="badge">AI: explain only</span><span class="badge">v0.2 · synthetic data</span></div>
  </header>

  <section class="stats">
    <div class="card stat"><span class="label">Active units</span><b id="activeCount">—</b></div>
    <div class="card stat"><span class="label">Station events</span><b id="eventCount">—</b></div>
    <div class="card stat"><span class="label">Pending / retry</span><b id="pendingCount">—</b></div>
    <div class="card stat"><span class="label">Delivered</span><b id="deliveredCount">—</b></div>
    <div class="card stat"><span class="label">Open defects</span><b id="defectCount">—</b></div>
  </section>

  <div class="grid">
    <section class="card section">
      <div class="label">Operator console</div><h2>Unit execution</h2>
      <div class="unitbar"><select id="unitSelect"><option>ACN-DEMO-0001</option><option>ACN-DEMO-0002</option><option>ACN-DEMO-0003</option></select><button id="reload" class="alt">Refresh evidence</button><span id="localBadge" class="status">Local state</span></div>
      <div class="facts"><div class="fact"><span class="label">Current station</span><strong id="station">—</strong></div><div class="fact"><span class="label">Operation</span><strong id="operation">—</strong></div><div class="fact"><span class="label">WIP state</span><strong id="wip">—</strong></div><div class="fact"><span class="label">Attempt</span><strong id="attempt">—</strong></div></div>
      <div id="route" class="route"></div>
      <div class="label">Interfaces</div><div id="interfaces" class="interfaces"></div>
      <div class="label" style="margin-top:12px">BOM progress</div><div id="requirements" class="requirements"></div>

      <div class="actions" style="margin-top:17px">
        <div class="action"><h3>1 · Verify MAC association</h3><div class="row"><select id="interfaceName"><option>wlan0</option><option>eth0</option></select><input id="mac" value="02:54:47:00:01:01" aria-label="MAC address"><button id="checkMac">Check</button></div></div>
        <div class="action"><h3>2 · Collect approved key part</h3><div class="row"><select id="partNo"><option>CTRL-A100</option><option>CTRL-A101</option><option>SENSOR-T200</option><option>SENSOR-T201</option><option>UNLISTED-X999</option></select><input id="kpsn" value="KPSN-DEMO-001" aria-label="Key-part serial"><button id="collectKp">Bind</button></div></div>
        <div class="action"><h3>3 · Complete current station</h3><div class="row"><button id="pass">PASS current</button><button id="fail" class="danger">Inject FAIL</button></div></div>
        <div class="action"><h3>4 · Repair evidence</h3><div class="row"><input id="repairNotes" value="Synthetic component reseated" aria-label="Repair notes"><button id="repair" class="warn">Record action</button></div></div>
        <div class="action full"><h3>Fault lab · local state and upstream delivery are separate</h3><div class="row"><button id="mesOnline" class="alt">Mock MES online</button><button id="mesOffline" class="alt">Simulate outage</button><button id="reset" class="alt">Reset synthetic demo</button></div><div class="fine">Demo controls are available only in combined demo mode. A stronger portfolio proof runs Edge and Mock MES as separate processes or hosts.</div></div>
      </div>
      <div id="console" class="console">Ready. Choose a unit and follow the highlighted route step.</div>
      <div id="explanation" class="explain" style="margin-top:10px">Reason-code explainer: deterministic and read-only.</div>
    </section>

    <aside style="display:grid;gap:16px;align-content:start">
      <section class="card section"><div class="label">Evidence chain</div><h2>Trace timeline</h2><div id="timeline" class="timeline"></div></section>
      <section class="card section"><div class="label">Store and forward</div><h2>Delivery outbox</h2><div style="overflow:auto"><table class="table"><thead><tr><th>Unit / station</th><th>Status</th><th>Try</th></tr></thead><tbody id="outbox"></tbody></table></div></section>
    </aside>
  </div>
  <div class="footer">Independent synthetic educational project · No employer, customer or factory source code, data, schema or workflow · Not a production MES</div>
</main>
<script>
const $=s=>document.querySelector(s);let unit=null,trace=null;
const routeSteps=[{n:10,c:'ST-IN',t:'Intake'},{n:20,c:'ST-ID',t:'Identity'},{n:30,c:'ST-KP',t:'Materials'},{n:40,c:'ST-FT',t:'Test'},{n:50,c:'ST-RP',t:'Repair'},{n:60,c:'ST-PK',t:'Pack'},{n:70,c:'ST-OUT',t:'Complete'}];
const reasons={ROUTE_VIOLATION:'The request is valid JSON, but the unit is at a different station. WIP was not advanced.',ASSOCIATION_MISMATCH:'The MAC format is valid, but its product association is wrong.',WRONG_INTERFACE:'The MAC belongs to this product but to a different network interface.',REQUIREMENT_NOT_SATISFIED:'A required verification or repair record is still missing.',QUANTITY_MISMATCH:'The required synthetic BOM quantities are incomplete.',KPSN_ALREADY_BOUND:'That component serial is already part of another genealogy record.',INVALID_SUBSTITUTE:'The part exists, but is not an approved substitute in this BOM group.',MATERIAL_NOT_IN_BOM:'The part is not present in the released synthetic BOM.',IDEMPOTENCY_CONFLICT:'The request ID was already used with a different payload; the server refused to guess.',OK:'The deterministic rule completed. Check delivery separately—local success is not upstream acknowledgement.'};
function rid(prefix){const uuid=globalThis.crypto?.randomUUID?.();return uuid?`${prefix}-${uuid}`:`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,14)}`}
function show(value,ok=true){const c=$('#console');c.className=`console ${ok?'ok':'bad'}`;c.textContent=typeof value==='string'?value:JSON.stringify(value,null,2);const code=value?.error?.code||value?.event?.reason_code||'OK';$('#explanation').textContent=`${code}: ${reasons[code]||value?.error?.message||'See the stored evidence and current route state.'}`}
async function api(path,opt={}){const response=await fetch(path,opt);let body;try{body=await response.json()}catch{body={ok:false,error:{code:'INVALID_RESPONSE',message:`HTTP ${response.status}`}}}if(!response.ok){show(body,false);throw body}return body}
function post(path,body){return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}
function sum(obj,...keys){return keys.reduce((n,k)=>n+Number(obj?.[k]||0),0)}
async function refresh(){try{const acn=$('#unitSelect').value;const [h,m,u,t,o]=await Promise.all([api('/api/v1/health'),api('/api/v1/metrics'),api(`/api/v1/units/${acn}`),api(`/api/v1/units/${acn}/trace`),api('/api/v1/outbox?limit=12')]);unit=u;trace=t;$('#healthText').textContent=h.status;$('#healthDot').classList.toggle('bad',!h.ok||h.status!=='healthy');$('#activeCount').textContent=m.products?.ACTIVE||0;$('#eventCount').textContent=sum(m.station_events,'PASS','FAIL');$('#pendingCount').textContent=sum(m.outbox,'PENDING','RETRY','IN_FLIGHT');$('#deliveredCount').textContent=m.outbox?.DELIVERED||0;$('#defectCount').textContent=m.quality?.open_defects||0;const x=u.unit;$('#station').textContent=x.station_code||'ROUTE COMPLETE';$('#operation').textContent=x.operation_code||'DONE';$('#wip').textContent=x.status;$('#attempt').textContent=x.attempt_no;$('#localBadge').textContent=`Local commit · v${x.wip_version}`;renderRoute(x.current_sequence);renderUnit(u);renderTrace(t);renderOutbox(o.outbox);prefillMac(u)}catch(e){if(e?.error?.code!=='UNKNOWN_ACN')console.error(e)}}
function renderRoute(current){const passed=new Set((trace?.station_events||[]).filter(e=>e.result==='PASS').map(e=>e.sequence));$('#route').innerHTML='';for(const s of routeSteps){const el=document.createElement('div');el.className=`step ${s.n===current?'current':passed.has(s.n)?'done':''}`;el.innerHTML=`<b>${s.c}</b>${s.t}`;$('#route').append(el)}}
function renderUnit(u){const i=$('#interfaces');i.innerHTML='';for(const x of u.interfaces){const el=document.createElement('span');el.className='chip';el.textContent=`${x.interface_name} · ${x.mac_address}`;i.append(el)}if(!u.interfaces.length)i.innerHTML='<span class="empty">No interfaces</span>';const r=$('#requirements');r.innerHTML='';for(const x of u.requirements){const el=document.createElement('span');el.className=`chip ${x.satisfied?'ok':'bad'}`;el.textContent=`${x.group_id}: ${x.collected_qty}/${x.required_qty}`;r.append(el)}if(!u.requirements.length)r.innerHTML='<span class="chip">No material requirement at this step</span>'}
function renderTrace(t){const target=$('#timeline');target.innerHTML='';const items=t.timeline||[];if(!items.length){target.innerHTML='<div class="empty">No accepted manufacturing evidence yet.</div>';return}for(const x of [...items].reverse()){const el=document.createElement('div');el.className='event';const title=document.createElement('div');title.textContent=x.summary;const small=document.createElement('small');small.textContent=`${x.type} · ${x.at}`;el.append(title,small);target.append(el)}}
function renderOutbox(rows){const b=$('#outbox');b.innerHTML='';if(!rows.length){b.innerHTML='<tr><td colspan="3" class="empty">No station event queued.</td></tr>';return}for(const x of rows){const tr=document.createElement('tr');const a=document.createElement('td');a.textContent=`${x.acn} · ${x.station_code}`;const s=document.createElement('td');s.textContent=x.status;s.className=x.status;const n=document.createElement('td');n.textContent=x.attempts;tr.append(a,s,n);b.append(tr)}}
function prefillMac(u){const name=$('#interfaceName').value;const found=u.interfaces.find(x=>x.interface_name===name);if(found)$('#mac').value=found.mac_address}
$('#reload').onclick=refresh;$('#unitSelect').onchange=async()=>{await refresh()};$('#interfaceName').onchange=()=>prefillMac(unit);
$('#checkMac').onclick=async()=>{try{show(await post('/api/v1/mac/check',{request_id:rid('ui-mac'),acn:$('#unitSelect').value,interface_name:$('#interfaceName').value,mac_address:$('#mac').value}));await refresh()}catch{}};
$('#collectKp').onclick=async()=>{try{show(await post('/api/v1/key-parts/collect',{request_id:rid('ui-kp'),acn:$('#unitSelect').value,part_no:$('#partNo').value,kpsn:$('#kpsn').value}));$('#kpsn').value=`KPSN-DEMO-${Date.now()}`;await refresh()}catch{}};
async function complete(result){try{const x=unit.unit;show(await post('/api/v1/stations/complete',{request_id:rid(`ui-${result.toLowerCase()}`),acn:x.acn,station_code:x.station_code,result,reason_code:result==='PASS'?'OK':'SYNTHETIC_TEST_NG',evidence:{source:'portfolio-dashboard',description:result==='FAIL'?'Injected synthetic failure':'Operator-confirmed synthetic evidence'}}));await refresh()}catch{}}
$('#pass').onclick=()=>complete('PASS');$('#fail').onclick=()=>complete('FAIL');
$('#repair').onclick=async()=>{try{const addressed=new Set((trace?.repair_actions||[]).filter(x=>x.status==='VERIFIED').map(x=>x.defect_id));const defect=(unit.defects||[]).find(x=>x.status==='OPEN'&&!addressed.has(x.defect_id));if(!defect){show({error:{code:'REQUIREMENT_NOT_SATISFIED',message:'No open defect still needs a repair action.'}},false);return}show(await post('/api/v1/repairs/actions',{request_id:rid('ui-repair'),acn:unit.unit.acn,defect_id:defect.defect_id,action_code:'RESEAT_SYNTHETIC_MODULE',notes:$('#repairNotes').value,technician:'demo-operator'}));await refresh()}catch{}};
async function mes(online){try{show(await post('/api/v1/demo/mes',{online}));setTimeout(refresh,800)}catch{}}
$('#mesOnline').onclick=()=>mes(true);$('#mesOffline').onclick=()=>mes(false);$('#reset').onclick=async()=>{if(!confirm('Reset only the synthetic TraceGate demo data?'))return;try{show(await post('/api/v1/demo/reset',{}));await refresh()}catch{}};
refresh();setInterval(refresh,4000);
</script></body></html>"""
